  "tg.localBf": "Trang quản lý trên máy con sẽ đóng khi Telegram mở (vào lại cần PIN). Nên tạo bot bằng Telegram trên điện thoại của bạn, rồi quay lại đây dán mã.", "tg.one": "Mỗi bé cần 1 bot riêng. Có 2 bé thì tạo 2 bot (vd: Nhà Bin, Nhà Na), mỗi bot dán vào trang của bé đó.", "tg.chatAlt": "Ví dụ cuộc trò chuyện với BotFather", "tg.bf1": "Đặt tên cho bot?", "tg.exName": "Nhà Bin", "tg.bf2": "Chọn tên đăng nhập, phải kết thúc bằng <b>bot</b>", "tg.exUser": "nhabin_kidguard_bot", "tg.bf3": "Xong! Token của bạn:", "tg.taken": "Báo tên đã có người dùng? Thêm vài số, vd: nhabin2026_bot.", "tg.s4h": "Liên kết Telegram của bạn", "tg.s4": "Trang hiện nút <b>Mở Telegram và liên kết</b> (và mã QR). Bấm nút, Telegram mở bot của bạn, bấm <b>Bắt đầu</b>. Xong: bot chào và hiện Menu.", "tg.paste": "Dán", "tg.pasteHand": "Trình duyệt không cho đọc bộ nhớ tạm: nhấn giữ ô và chọn Dán.", "tg.tokOk": "Token đúng dạng", "tg.tokBad": "Chưa thấy token (dạng 123456789:AA…)", "tg.linkHow": "Trên điện thoại có Telegram: bấm nút dưới, rồi bấm <b>Bắt đầu</b> trong bot. Đang ở máy tính: quét QR bằng camera điện thoại. Link không mở? Tự mở bot và gửi mã 6 số.", "tg.q1": "Chưa có Telegram?", "tg.a1": "Cài Telegram trên điện thoại bố mẹ (Play Store / App Store), đăng ký bằng số điện thoại, rồi làm từ bước 1. Máy con không cần cài Telegram.", "tg.q2": "Báo “Token sai” hoặc “đang được nơi khác dùng”?", "tg.a2": "Token sai: copy cả tin của BotFather rồi dán, trang tự lấy token. Đang được nơi khác dùng: bot đó đã gắn với máy khác, hãy tạo bot mới cho con này (mỗi con 1 bot). Lộ token: gửi /revoke cho BotFather để lấy token mới, rồi dán lại.", "tg.q3": "Bấm Bắt đầu mà bot không trả lời?", "tg.a3": "Mã liên kết dùng được 15 phút: bấm Mã khác rồi thử lại. Kiểm tra máy con có mạng (bot chạy trên máy con: máy con mất mạng thì bot im).", "tg.h": "Telegram", "tg.d": "Xem, điều khiển, nhận báo qua bot Telegram của nhà mình. Không cần IP, Tailscale hay relay", "tg.p": "Máy con tự chạy bot Telegram riêng của nhà bạn: gõ lệnh trong Telegram (/status, /bonus 30, /lock, /locate, /screen…) và nhận báo SOS, xin thêm giờ (có nút duyệt), app mới, nhập sai PIN kèm ảnh.", "tg.s1": "Bấm nút dưới để mở @BotFather (bot chính thức của Telegram), bấm <b>Bắt đầu</b>, rồi trả lời như sau:", "tg.s2": "Trong tin cuối của BotFather, chạm vào dòng token (dạng 123456789:AA…) là tự copy. Hoặc nhấn giữ cả tin → Sao chép: dán cả tin cũng được. Giữ kín token: ai có token là điều khiển được bot.", "tg.s3": "Máy con nhận token và tự chạy bot trong vài giây.", "tg.tok": "Token bot", "tg.connect": "Kết nối", "tg.privacy": "Tin nhắn, ảnh, ghi âm đi qua máy chủ Telegram (không mã hoá đầu cuối). Token chỉ lưu trên máy con. Máy con giữ 1 kết nối chờ tới Telegram (tốn rất ít pin/dữ liệu). Không có lệnh gỡ quản lý, huỷ ghép, xoá dữ liệu qua Telegram.", "tg.bot": "Bot", "tg.chats": "Chat đã liên kết", "tg.noChats": "Chưa có chat nào.", "tg.unlink": "Gỡ", "tg.codeP": "Hoặc mở {0} và gửi mã:", "tg.until": "hết hạn {0}", "tg.newCode": "Tạo mã liên kết", "tg.cmds": "Gõ /help trong bot để xem lệnh.", "tg.off": "Tắt bot Telegram", "tg.nChats": "{0} chat", "tg.setDone": "Đã gửi token cho máy con", "tg.codeDone": "Đã tạo mã mới", "tg.offDone": "Đã tắt bot", "tg.offAsk": "Tắt bot Telegram? Máy con quên token và mọi chat đã liên kết.", "tg.unDone": "Đã gỡ chat", "tg.unAsk": "Gỡ chat này? Chat đó không nhận báo và không điều khiển được nữa.", "tg.e.bad token": "Token sai. Copy lại đúng token từ @BotFather.", "tg.e.conflict": "Token này đang được nơi khác dùng (webhook hoặc app khác đọc tin). Mỗi bot chỉ dùng cho 1 máy con.", "tg.e.telegram unreachable": "Máy con không kết nối được Telegram.", "cr.tgSet.bad token": "Token sai. Copy lại đúng token từ @BotFather.", "cr.tgSet.telegram unreachable": "Máy con không kết nối được Telegram, thử lại sau.", "tg.s1h": "Tạo bot (khoảng 1 phút)", "tg.openBf": "Mở @BotFather", "tg.s2h": "Copy token", "tg.s3h": "Dán vào đây và bấm Kết nối", "tg.runs": "Bot đang chạy trên máy con", "tg.live": "Đang chạy", "tg.errTag": "Có lỗi", "tg.since": "Liên kết {0}", "tg.addFirst": "Liên kết Telegram của bạn", "tg.addMore": "Thêm người nhận (bố, mẹ, ông bà…)", "tg.qrAlt": "Mã QR mở bot Telegram", "tg.openLink": "Mở Telegram và liên kết", "tg.again": "Mã khác", "tg.max": "Đã đủ 5 chat. Gỡ bớt để thêm người.", "tg.tryH": "Dùng thế nào", "tg.tryP": "Trong bot bấm 📋 Menu để dùng nút bấm (không cần nhớ lệnh), hoặc gõ lệnh. Báo SOS, xin thêm giờ (có nút Cho/Từ chối), app mới, nhập sai PIN (kèm ảnh) tự gửi tới mọi chat đã liên kết.", "tg.noChatTag": "Chưa liên kết",
